/* ── 20-features.js ── */
// 20-features.js — the module accordions. Like the live reference: the open item follows the
// pointer, can be clicked, and auto-advances every few seconds while the list is on screen.
// A visual panel (data-target) shows the matching [data-feature-step] as .is-active.
(() => {
  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
  document.querySelectorAll('[data-features]').forEach(list => {
    const items = [...list.querySelectorAll('[data-feature]')];
    const interval = Number(list.dataset.interval) || 4500;
    const panel = list.dataset.target ? document.querySelector(list.dataset.target) : null;
    list.style.setProperty('--feature-interval', `${interval}ms`);
    let index = 0, timer = null, hovering = false, visible = false;

    const show = next => {
      index = (next + items.length) % items.length;
      items.forEach((item, i) => {
        const open = i === index;
        item.classList.toggle('is-open', open);
        item.classList.remove('is-timing');
        item.querySelector('.feature-title').setAttribute('aria-expanded', String(open));
      });
      panel?.querySelectorAll('[data-feature-step]').forEach(step => {
        const steps = step.dataset.featureStep.split(/\s+/).map(Number);
        step.classList.toggle('is-active', steps.includes(index));
      });
      panel?.setAttribute('data-active-step', String(index));
    };
    const schedule = () => {
      clearTimeout(timer);
      if (reduceMotion || hovering || !visible) return;
      const current = items[index];
      void current.offsetWidth; // restart the progress line
      current.classList.add('is-timing');
      timer = setTimeout(() => { show(index + 1); schedule(); }, interval);
    };

    items.forEach((item, i) => {
      item.addEventListener('pointerenter', event => { if (event.pointerType !== 'mouse') return; hovering = true; clearTimeout(timer); show(i); });
      item.querySelector('.feature-title').addEventListener('click', () => { show(i); schedule(); });
    });
    list.addEventListener('pointerleave', () => { hovering = false; schedule(); });
    new IntersectionObserver(([entry]) => { visible = entry.isIntersecting; visible ? schedule() : clearTimeout(timer); }, { threshold: 0.35 }).observe(list);
    show(0);
  });
})();

/* ── 31-sky.js ── */
// 31-sky.js — gentle parallax on the sky band art (max 60px either way). Off for reduced motion.
(() => {
  const art = document.querySelector('[data-sky-parallax]');
  if (!art || matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const band = art.parentElement;
  let ticking = false;
  const update = () => {
    ticking = false;
    const rect = band.getBoundingClientRect();
    if (rect.bottom < 0 || rect.top > innerHeight) return;
    const progress = (innerHeight - rect.top) / (innerHeight + rect.height); // 0 → 1 across the viewport
    art.style.transform = `translate3d(0, ${((progress - 0.5) * 120).toFixed(1)}px, 0)`;
  };
  addEventListener('scroll', () => { if (!ticking) { ticking = true; requestAnimationFrame(update); } }, { passive: true });
  addEventListener('resize', update);
  update();
})();

/* ── 33-how.js ── */
// 33-how.js — "How it works" carousel, timed like the live quote carousel: advances every
// 4.5s while on screen, pauses on hover/focus, tabs jump directly, arrow keys move between
// tabs. The step text animates word by word via CSS (.how-word transitions).
(() => {
  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
  document.querySelectorAll('[data-how]').forEach(root => {
    const tabs = [...root.querySelectorAll('[data-how-tab]')];
    const steps = [...root.querySelectorAll('[data-how-step]')];
    const frames = [...root.querySelectorAll('[data-how-frame]')];
    const strip = root.querySelector('.how-tabs');
    const interval = Number(root.dataset.interval) || 4500;
    root.style.setProperty('--how-interval', `${interval}ms`);
    let index = 0, timer = null, paused = false, visible = false;

    const show = next => {
      index = (next + tabs.length) % tabs.length;
      tabs.forEach((tab, i) => { const on = i === index; tab.classList.toggle('is-active', on); tab.setAttribute('aria-selected', String(on)); tab.tabIndex = on ? 0 : -1; });
      steps.forEach((step, i) => { const on = i === index; step.classList.toggle('is-active', on); step.setAttribute('aria-hidden', String(!on)); });
      frames.forEach((frame, i) => frame.classList.toggle('is-active', i === index));
      // On phones the tab row scrolls sideways: keep the active tab in view without moving the page.
      if (strip.scrollWidth > strip.clientWidth) {
        const offset = tabs[index].getBoundingClientRect().left - strip.getBoundingClientRect().left;
        strip.scrollTo({ left: strip.scrollLeft + offset - (strip.clientWidth - tabs[index].offsetWidth) / 2, behavior: reduceMotion ? 'auto' : 'smooth' });
      }
    };
    const schedule = () => {
      clearTimeout(timer);
      root.classList.remove('is-timing');
      if (reduceMotion || paused || !visible) return;
      void root.offsetWidth; // restart the progress line
      root.classList.add('is-timing');
      timer = setTimeout(() => { show(index + 1); schedule(); }, interval);
    };

    tabs.forEach((tab, i) => {
      tab.addEventListener('click', () => { show(i); schedule(); });
      tab.addEventListener('keydown', event => {
        const offset = event.key === 'ArrowRight' ? 1 : event.key === 'ArrowLeft' ? -1 : 0;
        if (!offset) return;
        event.preventDefault(); show(index + offset); tabs[index].focus(); schedule();
      });
    });
    const card = root.querySelector('.how-card');
    card.addEventListener('pointerenter', () => { paused = true; schedule(); });
    card.addEventListener('pointerleave', () => { paused = false; schedule(); });
    root.addEventListener('focusin', event => { if (event.target.matches(':focus-visible')) { paused = true; schedule(); } });
    root.addEventListener('focusout', event => { if (!root.contains(event.relatedTarget)) { paused = false; schedule(); } });

    // Hold the first step's words until the card scrolls into view, then let them blur in.
    if (!reduceMotion) root.classList.add('is-waiting');
    new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      if (visible) root.classList.remove('is-waiting');
      schedule();
    }, { threshold: 0.4 }).observe(card);
    show(index);
  });
})();
